WITH base AS (SELECT id, device, started_at, country, COALESCE(browser, 'N/A') AS browser_filled, TO_DATE(started_at) AS started_at_date, COALESCE(country, 'UNKNOWN') AS resolved_country FROM sessions WHERE started_at > TO_TIMESTAMP('2024-01-26 15:00:00') AND browser IN ('Edge', 'Firefox')), not_flagged AS (SELECT s.* FROM base s WHERE NOT EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.event_time >= s.started_at)), base_sessions AS (SELECT id, device, started_at, country, browser_filled, started_at_date, resolved_country, DATE_TRUNC('month', started_at_date) AS started_at_date_period FROM not_flagged WHERE device IN ('mobile', 'tablet', 'desktop')), prev_events AS (SELECT *, LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) AS prev_started_at FROM base_sessions), flagged AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM prev_events), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at_date, id) AS rn FROM islands QUALIFY rn = 1) SELECT id, device, started_at, country, browser_filled, started_at_date, resolved_country, started_at_date_period, prev_started_at FROM ranked ORDER BY country NULLS LAST
